using Romd.Media.Chd;
using Shouldly;
using Xunit;

namespace Romd.Media.Tests.Chd;

public sealed class ChdHeaderPreflightTests
{
    private static readonly ChdHeaderPreflightLimits FrozenLimits = new(10L << 30, 10UL << 30, 1U << 20, 2621440);

    public static TheoryData<string> HeaderCases
    {
        get
        {
            var names = new TheoryData<string>();
            foreach (string name in Cases.Keys)
                names.Add(name);
            return names;
        }
    }

    [Theory]
    [MemberData(nameof(HeaderCases))]
    public void Inspect_FrozenHeaderCase_ReturnsPreciseFactsOrCause(string caseId)
    {
        // Arrange: explicit byte vectors and independent expected facts; no file/native/body access.
        HeaderCase testCase = Cases[caseId];
        byte[] header = Convert.FromHexString(testCase.HeaderHex);

        // Act
        ChdHeaderPreflightResult result = ChdHeaderPreflight.Inspect(header, testCase.ArtifactBytes, FrozenLimits);

        // Assert
        if (testCase.Cause is { } cause)
        {
            var rejected = result.ShouldBeOfType<ChdHeaderPreflightResult.Rejected>();
            rejected.Cause.ShouldBe(cause);
            rejected.CodecSlot.ShouldBe(testCase.CodecSlot);
            rejected.Codec.ShouldBe(testCase.Codec);
        }
        else
        {
            var accepted = result.ShouldBeOfType<ChdHeaderPreflightResult.Accepted>();
            accepted.Facts.ShouldBe(testCase.Facts);
        }
    }

    private sealed record HeaderCase(string HeaderHex, long ArtifactBytes, ChdHeaderPreflightCause? Cause,
        int? CodecSlot, uint? Codec, ChdHeaderFacts? Facts);

